import pytest
from axis_streamer_regmap_pkg.reg_model import RegModel
from axis_streamer_regmap_pkg.sim import Simulator
from axis_streamer_regmap_pkg.lib import NormalCallbackSet


def make_sim_regs():
    sim = Simulator(address=0)
    return RegModel(
        callbacks=NormalCallbackSet(
            read_callback=sim.read,
            write_callback=sim.write,
            read_block_callback=sim.read_block,
            write_block_callback=sim.write_block,
        )
    )


@pytest.fixture
def regs():
    return make_sim_regs()


def test_reset_values(regs):
    assert regs.START_REG.START.read() == 0
    assert regs.FLUSH_REG.FLUSH.read() == 0
    assert regs.MODE_REG.MODE.read() == 0
    assert regs.NSAMP_REG.NSAMP.read() == 0


def test_register_offsets(regs):
    assert regs.START_REG.address == 0x0
    assert regs.FLUSH_REG.address == 0x4
    assert regs.MODE_REG.address == 0x8
    assert regs.NSAMP_REG.address == 0xc
    assert regs.LOST_REG.address == 0x10
    assert regs.STATUS_REG.address == 0x14


def test_field_roundtrip(regs):
    regs.START_REG.START.write(0x1)
    assert regs.START_REG.START.read() == 0x1
    regs.START_REG.START.write(0)
    regs.FLUSH_REG.FLUSH.write(0x1)
    assert regs.FLUSH_REG.FLUSH.read() == 0x1
    regs.FLUSH_REG.FLUSH.write(0)
    regs.MODE_REG.MODE.write(0x1)
    assert regs.MODE_REG.MODE.read() == 0x1
    regs.MODE_REG.MODE.write(0)
    regs.NSAMP_REG.NSAMP.write(0xdeadbeef)
    assert regs.NSAMP_REG.NSAMP.read() == 0xdeadbeef
    regs.NSAMP_REG.NSAMP.write(0)


def test_register_independence(regs):
    regs.START_REG.START.write(0x1)
    regs.FLUSH_REG.FLUSH.write(0x1)
    regs.MODE_REG.MODE.write(0x1)
    regs.NSAMP_REG.NSAMP.write(0xabcd)
    assert regs.START_REG.START.read() == 0x1
    assert regs.FLUSH_REG.FLUSH.read() == 0x1
    assert regs.MODE_REG.MODE.read() == 0x1
    assert regs.NSAMP_REG.NSAMP.read() == 0xabcd
